mockPlayerFavorabilities.forEach((p) => {
  if (p.stadium && p.stadium.coordinates) {
    (p.stadium as any).latitude =
      p.stadium.latitude ?? p.stadium.coordinates.lat;
    (p.stadium as any).longitude =
      p.stadium.longitude ?? p.stadium.coordinates.lon;
  }
  const boardEntry = mockCosmicBoard.find(
    (b) => String(b.id) === String(p.player_id),
  );
  const spirit = p.spirit_score ?? boardEntry?.spirit_score ?? 85.0;
  p.spirit_score = spirit;
  const baseSpirit = Math.round(spirit * 0.8 * 10) / 10;
  p.base_spirit = baseSpirit;
  const venueBonus = p.stadium?.roof_type?.includes('Dome') ? 5.0 : 10.0;
  const healthPen = p.health_penalty ?? 0.0;
  p.health_penalty = healthPen;
  p.role_modifier =
    Math.round(
      (p.favorability_score - baseSpirit - healthPen - venueBonus) * 10,
    ) / 10;
  p.astrological_rationale = p.astrological_rationale || p.rationale;
  p.astrological_transit =
    p.astrological_transit || (p.aspect_highlights || []).join(' • ');
});

